/**
 * EdiImportPage – common EDI (Excel import) page, built on SheetJS (xlsx).
 *
 * Usage:
 *   <EdiImportPage tableKey="BANK" />
 *   <EdiImportPage tableKey="LEAVE_TYPE" mandatoryMode="A" onSubmit={saveRows} />
 *   <EdiImportPage
 *     tableKey="EMPLOYEE"
 *     autoGeneratedColumns={["EMPLOYEE_ID", "EMPLOYEE_CODE"]}
 *   />
 *
 * Flow:
 *   1. On mount (or when tableKey changes) it calls
 *      PROC_BUILD_DYNAMIC_EDI_OPERATIONS('EDI_EXCEL_TEMPLATE', code1 = tableKey, code2 = mode)
 *      through getDynamicLookupaccount, which returns the column metadata.
 *   2. "Download template" builds an .xlsx with one header per column, a note on each header
 *      (type / length / mandatory), text + date cell formats, and a "Columns" sheet that lists
 *      every rule.
 *   3. "Upload Excel" reads the filled file, validates every cell against the same metadata
 *      (type, length, precision, scale, mandatory) and shows the rows in an editable grid.
 *      Bad cells and bad rows are red; fixing a cell re-validates it live.
 *   4. "Save rows" sends ALL rows + the ediKey (tableKey) in one call (executeEdiSave) unless a
 *      parent supplies its own onSubmit. COMPANY_CODE is added to every row from the logged-in user.
 *   5. If the server finds values that do not exist in the parent (master) tables, it rejects the
 *      whole save and returns the bad rows (EdiInvalidRowsError). Those cells turn red with the
 *      server message; fixing a cell clears its error and Save is re-enabled once all rows are clean.
 *
 * Requires:  npm i xlsx
 *
 * NOTE: the free SheetJS build cannot write Excel data-validation rules or cell colours, so Excel
 * itself will not block a wrong value while typing. All type / length rules are enforced here on upload.
 */
import { AlertTriangle, CheckCircle2, ChevronLeft, ChevronRight, Download, FileSpreadsheet, RefreshCw, Save, Trash2, Upload, X } from "lucide-react";
import { ChangeEvent, useCallback, useEffect, useMemo, useRef, useState } from "react";
import * as XLSX from "xlsx";
import {
  DynamicQueryParams,
  executeEdiSave,
  getDynamicLookupaccount,
  EdiInvalidRowsError,
  EdiInvalidRow,
} from "../api/lookups";import { Button } from "./ui/Button";
import AutoDismissAlert from "./ui/AutoDismissAlert";
import { useAuth } from "../state/AuthContext";


/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

type ColumnKind = "text" | "number" | "date";
/** Y = mandatory columns only, N = optional columns only, A = all columns (matches P_CODE2). */
type MandatoryMode = "Y" | "N" | "A";

export type EdiColumn = {
  columnId: number;
  name: string;
  dataType: string;
  length: number | null; // text max length (null = unlimited, e.g. CLOB)
  precision: number | null;
  scale: number | null;
  nullable: boolean;
  kind: ColumnKind;
  typeLabel: string; // e.g. VARCHAR2(50), NUMBER(10,2), DATE
};

type EdiRow = {
  id: number;
  values: Record<string, string>; // everything held as string while editing; dates as yyyy-mm-dd
  errors: Record<string, string>; // column name -> message
};

export type EdiImportPageProps = {
  /** Key understood by the procedure, e.g. "BANK", "LEAVE_TYPE", "ATTENDANCE", "EMPLOYEE". */
  tableKey: string;
  title?: string;
  mandatoryMode?: MandatoryMode;
  /** Download the template as soon as the columns are fetched. */
  autoDownload?: boolean;
  /**
   * Column names that are system-generated / key-managed.
   * These are still shown in the template and grid (needed for updates),
   * but are treated as optional so blank values pass validation (INSERT path).
   * Example for EMPLOYEE: ["EMPLOYEE_ID", "EMPLOYEE_CODE"]
   */
  autoGeneratedColumns?: string[];
  /**
   * Optional override. Called with clean rows (empty -> null, dates as yyyy-mm-dd, COMPANY_CODE added).
   * To get the same red-cell feedback for parent-table errors, throw an EdiInvalidRowsError from here.
   */
  onSubmit?: (rows: Record<string, string | null>[], columns: EdiColumn[]) => Promise<void> | void;
  /** Shows a Close (X) button in the header, used when the page is opened from a master list. */
  onClose?: () => void;
};

type Notice = { type: "success" | "error"; message: string } | null;

const TEMPLATE_SHEET = "Template";
const TEMPLATE_ROWS = 500; // pre-formatted rows in the template
const PAGE_SIZE = 50;
/** Filled automatically from the logged-in user, so it is hidden from the template and the grid. */
const COMPANY_COLUMN = "COMPANY_CODE";

/* ------------------------------------------------------------------ */
/*  API call                                                           */
/* ------------------------------------------------------------------ */

/**
 * ADJUST the property names here if your DynamicQueryParams uses different keys.
 * Parameter order follows the procedure: P_PARAMETER, P_LOGINID, P_CODE1 (table key),
 * P_CODE2 (Y / N / A).
 */
function buildColumnQuery(tableKey: string, mode: MandatoryMode, loginid: string): DynamicQueryParams {
  return {
    parameter: "EDI_EXCEL_TEMPLATE",
    loginid,
    code1: tableKey,
    code2: mode,
  } as unknown as DynamicQueryParams;
}

function pick(row: Record<string, unknown>, key: string): unknown {
  const hit = Object.keys(row).find((k) => k.toLowerCase() === key);
  return hit ? row[hit] : undefined;
}

const toNum = (v: unknown): number | null => {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

function toColumn(row: Record<string, unknown>): EdiColumn | null {
  const name = String(pick(row, "column_name") ?? "").trim();
  if (!name) return null;
  const dataType = String(pick(row, "data_type") ?? "").toUpperCase();
  const dataLength = toNum(pick(row, "data_length"));
  const precision = toNum(pick(row, "data_precision"));
  const scale = toNum(pick(row, "data_scale"));
  const nullable = String(pick(row, "nullable") ?? "Y").toUpperCase() !== "N";

  let kind: ColumnKind = "text";
  if (dataType.includes("DATE") || dataType.startsWith("TIMESTAMP")) kind = "date";
  else if (["NUMBER", "FLOAT", "INTEGER", "BINARY_FLOAT", "BINARY_DOUBLE"].includes(dataType)) kind = "number";

  const unlimited = ["CLOB", "NCLOB", "LONG"].includes(dataType);
  const length = kind === "text" && !unlimited ? dataLength : null;

  let typeLabel = dataType;
  if (kind === "text" && length) typeLabel = `${dataType}(${length})`;
  if (kind === "number" && precision !== null) {
    typeLabel = `${dataType}(${precision}${scale !== null && scale > 0 ? `,${scale}` : ""})`;
  }

  return {
    columnId: toNum(pick(row, "column_id")) ?? 0,
    name,
    dataType,
    length,
    precision,
    scale,
    nullable,
    kind,
    typeLabel,
  };
}

/* ------------------------------------------------------------------ */
/*  Validation                                                         */
/* ------------------------------------------------------------------ */

function isValidIsoDate(v: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
  const [y, m, d] = v.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}

export function validateCell(col: EdiColumn, raw: string | undefined): string | null {
  const v = (raw ?? "").trim();
  if (!v) return col.nullable ? null : "Required";

  if (col.kind === "text") {
    if (col.length && v.length > col.length) return `Max ${col.length} characters (entered ${v.length})`;
    return null;
  }

  if (col.kind === "number") {
    if (!/^[-+]?(\d+\.?\d*|\.\d+)$/.test(v)) return "Must be a number";
    const [intPart, decPart = ""] = v.replace(/^[-+]/, "").split(".");
    const intDigits = intPart.replace(/^0+/, "").length;
    const decDigits = decPart.replace(/0+$/, "").length;
    if (col.scale === 0 && decDigits > 0) return "Whole number only";
    if (col.scale && col.scale > 0 && decDigits > col.scale) return `Max ${col.scale} decimal places`;
    if (col.precision !== null && col.scale !== null) {
      const maxInt = col.precision - col.scale;
      if (intDigits > maxInt) return `Max ${maxInt} digits before the decimal point`;
    }
    return null;
  }

  return isValidIsoDate(v) ? null : "Invalid date (use dd/mm/yyyy)";
}

function validateRow(columns: EdiColumn[], values: Record<string, string>): Record<string, string> {
  const errors: Record<string, string> = {};
  columns.forEach((col) => {
    const msg = validateCell(col, values[col.name]);
    if (msg) errors[col.name] = msg;
  });
  return errors;
}

/* ------------------------------------------------------------------ */
/*  Excel helpers (SheetJS)                                            */
/* ------------------------------------------------------------------ */

const pad = (n: number) => String(n).padStart(2, "0");

/** SheetJS builds Date cells in local time; +12h keeps us safe from tiny offset drift. */
function localDateToIso(d: Date): string {
  const x = new Date(d.getTime() + 12 * 3600 * 1000);
  return `${x.getFullYear()}-${pad(x.getMonth() + 1)}-${pad(x.getDate())}`;
}

/** Excel serial number (days since 1899-12-30) -> yyyy-mm-dd. */
function serialToIso(n: number): string {
  const d = new Date(Math.round((n - 25569) * 86400 * 1000));
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
}

function normalizeDateString(v: string): string {
  const s = v.trim();
  const dmy = s.match(/^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})$/);
  if (dmy) return `${dmy[3]}-${pad(Number(dmy[2]))}-${pad(Number(dmy[1]))}`;
  const iso = s.match(/^(\d{4}-\d{2}-\d{2})/);
  return iso ? iso[1] : s;
}

function cellToString(value: unknown, kind: ColumnKind): string {
  if (value === null || value === undefined) return "";
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? "" : localDateToIso(value);
  if (typeof value === "number") return kind === "date" ? serialToIso(value) : String(value);
  if (typeof value === "boolean") return value ? "1" : "0";
  const s = String(value);
  return kind === "date" ? normalizeDateString(s) : s;
}

function buildTemplate(
  tableKey: string,
  columns: EdiColumn[],
  autoGeneratedSet: Set<string>,
) {
  const wb = XLSX.utils.book_new();

  // Template sheet: header row only
  const ws = XLSX.utils.aoa_to_sheet([columns.map((c) => c.name)]);
  ws["!cols"] = columns.map((c) => ({
    wch: Math.min(40, Math.max(c.name.length + 4, c.length ? Math.min(c.length, 30) : 14)),
  }));

  columns.forEach((c, i) => {
    const colNo = i;
    const isAuto = autoGeneratedSet.has(c.name.toUpperCase());

    // header note: type / mandatory (+ hint for auto-generated)
    const head = ws[XLSX.utils.encode_cell({ r: 0, c: colNo })];
    if (head) {
      const noteLines = [
        c.typeLabel,
        c.nullable ? "Optional" : "Mandatory",
      ];
      if (isAuto) noteLines.push("Leave blank for new records");
      head.c = [{ a: "EDI", t: noteLines.join("\n") }];
      head.c.hidden = true;
    }

    // pre-format the data rows: text stays text (keeps leading zeros), dates show dd/mm/yyyy
    if (c.kind !== "number") {
      for (let r = 1; r <= TEMPLATE_ROWS; r++) {
        ws[XLSX.utils.encode_cell({ r, c: colNo })] = {
          t: "s",
          v: "",
          z: c.kind === "date" ? "dd/mm/yyyy" : "@",
        };
      }
    }
  });
  ws["!ref"] = XLSX.utils.encode_range({
    s: { r: 0, c: 0 },
    e: { r: TEMPLATE_ROWS, c: Math.max(columns.length - 1, 0) },
  });
  XLSX.utils.book_append_sheet(wb, ws, TEMPLATE_SHEET);

  // Columns sheet: the rules
  const info = XLSX.utils.aoa_to_sheet([
    ["#", "Column", "Type", "Max length", "Precision", "Scale", "Mandatory", "Rule"],
    ...columns.map((c, i) => [
      i + 1,
      c.name,
      c.dataType,
      c.length ?? "",
      c.precision ?? "",
      c.scale ?? "",
      c.nullable ? "No" : "Yes",
      ruleText(c, autoGeneratedSet.has(c.name.toUpperCase())),
    ]),
  ]);
  info["!cols"] = [
    { wch: 5 },
    { wch: 28 },
    { wch: 14 },
    { wch: 11 },
    { wch: 10 },
    { wch: 7 },
    { wch: 11 },
    { wch: 70 },
  ];
  XLSX.utils.book_append_sheet(wb, info, "Columns");

  XLSX.writeFile(wb, `${tableKey.toLowerCase()}_edi_template.xlsx`);
}

function ruleText(c: EdiColumn, isAutoGenerated: boolean): string {
  let base: string;
  if (c.kind === "text") base = c.length ? `Text, up to ${c.length} characters` : "Text";
  else if (c.kind === "date") base = "Date, dd/mm/yyyy";
  else if (c.precision === null || c.scale === null) base = "Number";
  else if (c.scale === 0) base = `Whole number, up to ${c.precision} digits`;
  else base = `Number, up to ${c.precision - c.scale} digits before and ${c.scale} after the decimal point`;

  if (isAutoGenerated) return `${base} (leave blank for new records)`;
  return base;
}

/** Reads the uploaded workbook into EdiRow[] using the fetched column metadata. */
async function readWorkbook(file: File, columns: EdiColumn[]) {
  const wb = XLSX.read(await file.arrayBuffer(), { type: "array", cellDates: true });
  const ws = wb.Sheets[TEMPLATE_SHEET] ?? wb.Sheets[wb.SheetNames[0]];
  if (!ws) throw new Error("The file has no worksheet.");

  const grid = XLSX.utils.sheet_to_json<unknown[]>(ws, {
    header: 1,
    raw: true,
    defval: "",
    blankrows: false,
  });
  if (!grid.length) throw new Error("The file is empty.");

  const byHeader = new Map(columns.map((c) => [c.name.toUpperCase(), c]));
  const colIndexToColumn = new Map<number, EdiColumn>();
  const unknownHeaders: string[] = [];

  (grid[0] || []).forEach((cell, idx) => {
    const h = String(cell ?? "").trim().toUpperCase();
    if (!h) return;
    const col = byHeader.get(h);
    if (col) colIndexToColumn.set(idx, col);
    else unknownHeaders.push(h);
  });

  const found = new Set(colIndexToColumn.values());
  const missing = columns.filter((c) => !c.nullable && !found.has(c)).map((c) => c.name);
  if (missing.length) {
    throw new Error(
      `Missing mandatory column(s): ${missing.join(", ")}. Please use the downloaded template.`,
    );
  }
  if (!colIndexToColumn.size) {
    throw new Error("No matching columns found. Please use the downloaded template.");
  }

  const rows: EdiRow[] = [];
  for (let r = 1; r < grid.length; r++) {
    const line = grid[r] || [];
    const values: Record<string, string> = {};
    columns.forEach((c) => (values[c.name] = ""));
    let hasData = false;
    colIndexToColumn.forEach((col, idx) => {
      const s = cellToString(line[idx], col.kind);
      values[col.name] = s;
      if (s.trim()) hasData = true;
    });
    if (hasData) rows.push({ id: 0, values, errors: {} });
  }

  return { rows, unknownHeaders };
}

/* ------------------------------------------------------------------ */
/*  Page                                                               */
/* ------------------------------------------------------------------ */

export function EdiImportPage({
  tableKey,
  title,
  mandatoryMode = "A",
  autoDownload = false,
  autoGeneratedColumns, // no "= []" default: a new array every render would refetch columns
  onSubmit,
  onClose,
}: EdiImportPageProps) {
  const { user } = useAuth();
  const loginid = user?.loginid || "ADMIN";
  // ADJUST to the field your AuthContext user really exposes
  const companyCode = String(
    (user as any)?.companyCode ?? (user as any)?.company_code ?? "",
  ).trim();

  const [mode, setMode] = useState<MandatoryMode>(mandatoryMode);
  const [columns, setColumns] = useState<EdiColumn[]>([]);
  const [loadingCols, setLoadingCols] = useState(true);
  const [rows, setRows] = useState<EdiRow[]>([]);
  const [fileName, setFileName] = useState("");
  const [notice, setNotice] = useState<Notice>(null);
  const [busy, setBusy] = useState(false);
  const [errorsOnly, setErrorsOnly] = useState(false);
  const [page, setPage] = useState(0);
  const fileRef = useRef<HTMLInputElement | null>(null);
  const nextId = useRef(1);

  const heading = title || `EDI Import – ${tableKey}`;

  /** Stable string key: changes only when the column NAMES change, not when the array identity does. */
  const autoGenKey = (autoGeneratedColumns ?? [])
    .map((n) => n.toUpperCase())
    .sort()
    .join("|");

  /** Upper-cased set for O(1) lookups; rebuilt only when the key changes */
  const autoGeneratedSet = useMemo(
    () => new Set(autoGenKey ? autoGenKey.split("|") : []),
    [autoGenKey],
  );

  /* ── fetch column metadata on mount / key change ── */
  const loadColumns = useCallback(async () => {
    setLoadingCols(true);
    setColumns([]);
    setRows([]);
    setFileName("");
    setNotice(null);
    try {
      const data = await getDynamicLookupaccount(buildColumnQuery(tableKey, mode, loginid));
      const cols = (data as Record<string, unknown>[])
        .map(toColumn)
        // COMPANY_CODE comes from the logged-in user, so the user never fills it
        .filter((c): c is EdiColumn => c !== null && c.name.toUpperCase() !== COMPANY_COLUMN)
        .map((c) => {
          // Treat auto-generated keys as optional so INSERT rows (blank ID) pass validation
          if (autoGeneratedSet.has(c.name.toUpperCase())) {
            return { ...c, nullable: true };
          }
          return c;
        })
        .sort((a, b) => a.columnId - b.columnId);

      if (!cols.length) {
        setNotice({
          type: "error",
          message: `No columns found for "${tableKey}". Check the table key.`,
        });
      }
      setColumns(cols);
      if (cols.length && autoDownload) buildTemplate(tableKey, cols, autoGeneratedSet);
    } catch (e) {
      setNotice({
        type: "error",
        message: e instanceof Error ? e.message : "Unable to load table columns",
      });
    } finally {
      setLoadingCols(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tableKey, mode, loginid, autoGeneratedSet]);

  useEffect(() => {
    void loadColumns();
  }, [loadColumns]);

  /* ── actions ── */
  const downloadTemplate = () => {
    try {
      buildTemplate(tableKey, columns, autoGeneratedSet);
    } catch (e) {
      setNotice({
        type: "error",
        message: e instanceof Error ? e.message : "Unable to create template",
      });
    }
  };

  const onFile = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = ""; // allow re-uploading the same file
    if (!file) return;
    setBusy(true);
    setNotice(null);
    try {
      const { rows: parsed, unknownHeaders } = await readWorkbook(file, columns);
      if (!parsed.length) {
        setRows([]);
        setNotice({ type: "error", message: "No data rows found in the file." });
        return;
      }
      const prepared = parsed.map((r) => ({
        ...r,
        id: nextId.current++,
        errors: validateRow(columns, r.values),
      }));
      setRows(prepared);
      setFileName(file.name);
      setPage(0);
      setErrorsOnly(false);
      const bad = prepared.filter((r) => Object.keys(r.errors).length).length;
      const extra = unknownHeaders.length
        ? ` Ignored unknown column(s): ${unknownHeaders.join(", ")}.`
        : "";
      setNotice({
        type: bad ? "error" : "success",
        message: bad
          ? `${prepared.length} rows loaded, ${bad} with errors (shown in red). Fix them below.${extra}`
          : `${prepared.length} rows loaded, all valid.${extra}`,
      });
    } catch (e) {
      setNotice({
        type: "error",
        message: e instanceof Error ? e.message : "Unable to read the Excel file",
      });
    } finally {
      setBusy(false);
    }
  };

  const updateCell = (id: number, col: EdiColumn, value: string) => {
    setRows((prev) =>
      prev.map((r) => {
        if (r.id !== id) return r;
        const values = { ...r.values, [col.name]: value };
        const errors = { ...r.errors };
        const msg = validateCell(col, value);
        if (msg) errors[col.name] = msg;
        else delete errors[col.name];
        return { ...r, values, errors };
      }),
    );
  };

  const removeRow = (id: number) => setRows((prev) => prev.filter((r) => r.id !== id));

  const clearAll = () => {
    setRows([]);
    setFileName("");
    setNotice(null);
  };

  /* ── derived ── */
  const errorRowCount = useMemo(
    () => rows.filter((r) => Object.keys(r.errors).length).length,
    [rows],
  );
  const visibleRows = useMemo(
    () => (errorsOnly ? rows.filter((r) => Object.keys(r.errors).length) : rows),
    [rows, errorsOnly],
  );
  const pageCount = Math.max(1, Math.ceil(visibleRows.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount - 1);
  const pageRows = visibleRows.slice(safePage * PAGE_SIZE, safePage * PAGE_SIZE + PAGE_SIZE);
  const rowNumber = useMemo(() => new Map(rows.map((r, i) => [r.id, i + 1])), [rows]);

  /** Marks the cells the server rejected (parent value not found) and jumps to them. */
  const applyServerErrors = (err: EdiInvalidRowsError) => {
    // API row numbers are 1-based and correspond to submitted row order.
    const byRow = new Map(
      err.invalidRows.map((r) => [r.row, r.errors]),
    );

    setRows((prev) =>
      prev.map((r, idx) => {
        const serverErrors = byRow.get(idx + 1);

        if (!serverErrors) return r;

        const errors = { ...r.errors };

        serverErrors.forEach((e) => {
          errors[e.column] = e.message;
        });

        return {
          ...r,
          errors,
        };
      }),
    );

    // Automatically filter and display problematic rows.
    setErrorsOnly(true);
    setPage(0);

    // Show the actual API response message.
    setNotice({
      type: "error",
      message: err.message,
    });
  };

  const submit = async () => {
    if (errorRowCount || !rows.length) return;
    if (!companyCode) {
      setNotice({ type: "error", message: "Company code not found for the logged-in user." });
      return;
    }
    const clean = rows.map((r) => {
      const out: Record<string, string | null> = {};
      columns.forEach((c) => {
        const v = (r.values[c.name] ?? "").trim();
        out[c.name] = v === "" ? null : v;
      });
      out[COMPANY_COLUMN] = companyCode; // every row carries the user's company
      return out;
    });
    setBusy(true);
    try {
      // default: all rows + ediKey (tableKey) in ONE call. A parent can still override with onSubmit.
      if (onSubmit) await onSubmit(clean, columns);
      else await executeEdiSave(tableKey, clean, loginid);
      setNotice({ type: "success", message: `${clean.length} rows submitted successfully` });
      clearAll();
      if (onClose) onClose();
    } catch (e) {
      if (e instanceof EdiInvalidRowsError) {
        applyServerErrors(e);
      } else {
        setNotice({
          type: "error",
          message: e instanceof Error ? e.message : "Unable to save rows",
        });
      }
    } finally {
      setBusy(false);
    }
  };

  /* ── render ── */
  const inputType = (c: EdiColumn) => (c.kind === "date" ? "date" : "text");
  const colWidth = (c: EdiColumn) => Math.min(260, Math.max(130, (c.length ?? 14) * 8 + 40));

  return (
    <section className="freight-airline-tariff-screen wms-master-screen freight-ui-standard freight-dense-form grid gap-2 p-1">
      {/* header */}
      <div className="tariff-page-header flex flex-wrap items-center justify-between gap-2">
        <div className="flex min-w-0 items-center gap-3">
          <span className="tariff-page-icon">
            <FileSpreadsheet size={18} />
          </span>
          <div className="min-w-0">
            <h1 className="m-0 truncate text-lg font-bold leading-tight text-slate-900">{heading}</h1>
            <p className="m-0 text-xs text-slate-500">
              {loadingCols
                ? "Loading columns..."
                : `${columns.length} columns · download the template, fill it, then upload it here`}
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <select
            value={mode}
            onChange={(e) => setMode(e.target.value as MandatoryMode)}
            disabled={busy || loadingCols}
            title="Columns to include"
            className="h-8 rounded-lg border border-slate-300 bg-white px-2 text-xs font-semibold text-slate-700"
          >
            <option value="A">All columns</option>
            <option value="Y">Mandatory only</option>
            <option value="N">Optional only</option>
          </select>

          <Button
            type="button"
            variant="outline"
            onClick={downloadTemplate}
            disabled={busy || loadingCols || !columns.length}
            className="h-8 gap-1.5 text-xs font-semibold px-3 rounded-lg cursor-pointer"
          >
            <Download size={14} /> Download template
          </Button>

          <Button
            type="button"
            variant="outline"
            onClick={() => fileRef.current?.click()}
            disabled={busy || loadingCols || !columns.length}
            className="h-8 gap-1.5 text-xs font-semibold px-3 rounded-lg cursor-pointer"
          >
            <Upload size={14} /> Upload Excel
          </Button>
          <input ref={fileRef} type="file" accept=".xlsx,.xls" hidden onChange={onFile} />

          <Button
            type="button"
            variant="outline"
            size="icon"
            onClick={() => void loadColumns()}
            disabled={busy || loadingCols}
            title="Reload columns"
            aria-label="Reload columns"
            className="h-8 w-8 rounded-lg cursor-pointer"
          >
            <RefreshCw size={14} className={loadingCols ? "animate-spin" : ""} />
          </Button>

          {onClose && (
            <Button
              type="button"
              variant="outline"
              size="icon"
              onClick={onClose}
              disabled={busy}
              title="Close"
              aria-label="Close"
              className="h-8 w-8 rounded-lg cursor-pointer"
            >
              <X size={16} />
            </Button>
          )}
        </div>
      </div>

      <AutoDismissAlert notice={notice} onClose={() => setNotice(null)} />

      {/* empty state */}
      {!rows.length && (
        <div className="grid place-items-center rounded-xl border border-dashed border-slate-300 bg-white p-10 text-center">
          <FileSpreadsheet size={32} className="text-slate-400" />
          <p className="mt-2 mb-0 text-sm font-semibold text-slate-700">
            {loadingCols ? "Fetching table columns..." : "No file loaded"}
          </p>
          <p className="m-0 mt-1 max-w-md text-xs text-slate-500">
            Download the template, fill it in, and upload it. Rows with a wrong type or length are
            highlighted in red and can be corrected right here.
          </p>
        </div>
      )}

      {/* grid */}
      {rows.length > 0 && (
        <div className="grid gap-2 rounded-xl border border-slate-200 bg-white p-2">
          {/* summary bar */}
          <div className="flex flex-wrap items-center justify-between gap-2 px-1">
            <div className="flex flex-wrap items-center gap-3 text-xs">
              <span className="font-semibold text-slate-700">{fileName}</span>
              <span className="text-slate-500">{rows.length} rows</span>
              <span className="inline-flex items-center gap-1 font-semibold text-emerald-600">
                <CheckCircle2 size={14} /> {rows.length - errorRowCount} valid
              </span>
              <span
                className={`inline-flex items-center gap-1 font-semibold ${
                  errorRowCount ? "text-red-600" : "text-slate-400"
                }`}
              >
                <AlertTriangle size={14} /> {errorRowCount} with errors
              </span>
              <label className="inline-flex cursor-pointer items-center gap-1.5 text-slate-600">
                <input
                  type="checkbox"
                  checked={errorsOnly}
                  onChange={(e) => {
                    setErrorsOnly(e.target.checked);
                    setPage(0);
                  }}
                />
                Show errors only
              </label>
            </div>

            <div className="flex items-center gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={clearAll}
                disabled={busy}
                className="h-8 gap-1.5 text-xs font-semibold px-3 rounded-lg cursor-pointer"
              >
                <X size={14} /> Clear
              </Button>
              <Button
                type="button"
                onClick={submit}
                disabled={busy || errorRowCount > 0}
                title={errorRowCount ? "Fix all red rows first" : "Save rows"}
                className="h-8 gap-1.5 bg-[#00378C] text-white hover:bg-[#002d72] shadow-xs text-xs font-semibold px-4 rounded-lg cursor-pointer"
              >
                <Save size={14} /> {busy ? "Working..." : "Save rows"}
              </Button>
            </div>
          </div>

          {/* table */}
          <div
            className="overflow-auto rounded-lg border border-slate-200"
            style={{ maxHeight: "calc(100dvh - 260px)" }}
          >
            <table
              className="border-collapse text-xs"
              style={{ minWidth: columns.reduce((s, c) => s + colWidth(c), 120) }}
            >
              <thead className="sticky top-0 z-10">
                <tr className="bg-slate-100 text-left text-slate-700">
                  <th className="w-14 border-b border-slate-200 px-2 py-2">#</th>
                  {columns.map((c) => (
                    <th
                      key={c.name}
                      className="border-b border-l border-slate-200 px-2 py-2"
                      style={{ minWidth: colWidth(c) }}
                    >
                      <div className="font-semibold">
                        {c.name}
                        {!c.nullable && <span className="text-red-600"> *</span>}
                      </div>
                      <div className="font-normal text-[10.5px] text-slate-500">{c.typeLabel}</div>
                    </th>
                  ))}
                  <th className="w-10 border-b border-l border-slate-200 px-2 py-2" />
                </tr>
              </thead>
              <tbody>
                {pageRows.map((r) => {
                  const errCount = Object.keys(r.errors).length;
                  return (
                    <tr
                      key={r.id}
                      className={
                        errCount
                          ? "bg-red-50 border-l-4 border-l-red-500"
                          : "bg-white"
                      }
                    >
                      <td className="border-b border-slate-100 px-2 py-1 align-middle">
                        <span
                          className={`inline-flex items-center gap-1 font-semibold ${
                            errCount ? "text-red-600" : "text-slate-500"
                          }`}
                          title={errCount ? `${errCount} error(s) in this row` : "Row is valid"}
                        >
                          {errCount ? <AlertTriangle size={12} /> : null}
                          {rowNumber.get(r.id)}
                        </span>
                      </td>
                      {columns.map((c) => {
                        const err = r.errors[c.name];
                        return (
                          <td
                            key={c.name}
                            className={`border-b border-l p-0.5 align-top ${
                              err
                                ? "border-red-200 bg-red-50"
                                : "border-slate-100"
                            }`}
                          >
                            <input
                              type={inputType(c)}
                              value={r.values[c.name] ?? ""}
                              onChange={(e) => updateCell(r.id, c, e.target.value)}
                              title={err || c.typeLabel}
                              aria-invalid={Boolean(err)}
                              className={`h-7 w-full rounded border px-1.5 text-xs outline-none focus:ring-2 ${
                                err
                                  ? "border-red-500 bg-red-100 text-red-800 focus:ring-red-300"
                                  : "border-transparent bg-transparent text-slate-800 hover:border-slate-300 focus:border-[#00378C] focus:bg-white focus:ring-blue-200"
                              }`}
                            />
                            {err && (
                              <div className="px-1 pb-1 pt-1 text-[10px] leading-tight text-red-600 font-medium whitespace-normal">
                                <span className="inline-flex items-start gap-1">
                                  <AlertTriangle size={11} className="shrink-0 mt-0.5" />
                                  {err}
                                </span>
                              </div>
                            )}
                          </td>
                        );
                      })}
                      <td className="border-b border-l border-slate-100 px-1 text-center align-middle">
                        <button
                          type="button"
                          onClick={() => removeRow(r.id)}
                          title="Remove row"
                          aria-label="Remove row"
                          className="cursor-pointer rounded p-1 text-slate-500 hover:bg-red-50 hover:text-red-600"
                        >
                          <Trash2 size={14} />
                        </button>
                      </td>
                    </tr>
                  );
                })}
                {!pageRows.length && (
                  <tr>
                    <td colSpan={columns.length + 2} className="p-6 text-center text-slate-500">
                      No rows to show.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          {/* pager */}
          <div className="flex items-center justify-end gap-2 px-1 text-xs text-slate-600">
            <span>
              Page {safePage + 1} of {pageCount}
            </span>
            <Button
              type="button"
              variant="outline"
              size="icon"
              className="h-7 w-7"
              disabled={safePage === 0}
              onClick={() => setPage(safePage - 1)}
              aria-label="Previous page"
            >
              <ChevronLeft size={14} />
            </Button>
            <Button
              type="button"
              variant="outline"
              size="icon"
              className="h-7 w-7"
              disabled={safePage >= pageCount - 1}
              onClick={() => setPage(safePage + 1)}
              aria-label="Next page"
            >
              <ChevronRight size={14} />
            </Button>
          </div>
        </div>
      )}
    </section>
  );
}

export default EdiImportPage;